        eligible = {i for i, (c, frac) in enumerate(info)
                    if c == color and frac >= 0.65}
        result = []
        for step in range(2, length):
            for start in sorted(eligible):
                seq = []
                i = start
                while i in eligible:
                    seq.append(i)
                    i += step
                if len(seq) >= 3:
                    result.append(seq)
        # Keep distinct progressions.
        return list({tuple(x) for x in result})

    best = None
